// Функция для получения названия упражнения по имени GIF файла
function getExerciseNameByGif(gifFilename) {
    if (!gifFilename) return null;
    const info = EXERCISE_GIF_NAMES[gifFilename];
    return info ? info.name : null;
}

// Функция для получения информации об упражнении по GIF


// Функция для поиска GIF файлов по названию упражнения
function searchGifsByExerciseName(query) {
    if (!query) return Object.keys(EXERCISE_GIF_NAMES);
    const q = query.toLowerCase();
    return Object.keys(EXERCISE_GIF_NAMES).filter(gif => {
        const info = EXERCISE_GIF_NAMES[gif];
        return info && info.name.toLowerCase().includes(q);
    });
}

// Функция для получения всех GIF файлов из маппинга
function getAllMappedGifs() {
    return Object.keys(EXERCISE_GIF_NAMES).sort();
}

// Экспорт
window.ExerciseGifNames = {
    getExerciseNameByGif: getExerciseNameByGif,
    
    searchGifsByExerciseName: searchGifsByExerciseName,
    getAllMappedGifs: getAllMappedGifs,
    EXERCISE_GIF_NAMES: EXERCISE_GIF_NAMES
};